use num_complex::Complex64;
use sonium_bem::materials::{AmbientMedium, PorousLayer};

/// Frequency-independent representation of a boundary surface, ready to be
/// evaluated at any simulation frequency. Building this out of the per-freq
/// loop avoids re-running the absorption-to-flow-resistivity inversion at
/// every step.
#[derive(Debug, Clone)]
pub(super) enum ResolvedBoundary {
    Rigid,
    PorousLayer {
        layer: PorousLayer,
        medium: AmbientMedium,
    },
    /// Surface impedance Z (complex Pa·s/m). The admittance is ρc / Z, and the
    /// boundary contribution is `-i k ρc / Z`.
    Impedance {
        z: Complex64,
        rho_c: f64,
    },
    /// Specific admittance (β = ρc / Z). The boundary contribution is `-i k β`.
    Admittance(Complex64),
}

impl ResolvedBoundary {
    /// Produce the normalized surface admittance β = ρc / Zs used by the TBEM
    /// assembler.
    pub(super) fn normalized_admittance(&self, frequency: f64) -> anyhow::Result<Complex64> {
        anyhow::ensure!(
            frequency.is_finite() && frequency > 0.0,
            "material frequency must be finite and positive"
        );
        let value = match self {
            ResolvedBoundary::Rigid => Complex64::new(0.0, 0.0),
            ResolvedBoundary::PorousLayer { layer, medium } => {
                layer.try_normalized_admittance(frequency, *medium)?
            }
            ResolvedBoundary::Impedance { z, rho_c } => Complex64::new(*rho_c, 0.0) / *z,
            ResolvedBoundary::Admittance(beta) => *beta,
        };
        anyhow::ensure!(
            value.re.is_finite() && value.im.is_finite(),
            "material admittance is singular or nonfinite"
        );
        Ok(value)
    }

    /// Produce the per-frequency factor that the FEM assembler multiplies
    /// against the boundary mass matrix. With Sonium's `exp(-iωt)` convention,
    /// passive normalized admittance contributes `-ikβ` so wall and volume
    /// losses have the same dissipative sign.
    pub(super) fn admittance_term(&self, k: f64, frequency: f64) -> anyhow::Result<Complex64> {
        anyhow::ensure!(
            k.is_finite() && k > 0.0,
            "wavenumber must be finite and positive"
        );
        let value = Complex64::new(0.0, -k) * self.normalized_admittance(frequency)?;
        anyhow::ensure!(
            value.re.is_finite() && value.im.is_finite(),
            "boundary coefficient is nonfinite"
        );
        Ok(value)
    }
}
